import { CreateDateColumn, PrimaryGeneratedColumn, UpdateDateColumn } from 'typeorm';

/**
 * Base entity shared by most tables.
 *
 * Provides:
 *   - `id`: UUID primary key (generated by Postgres uuid-ossp)
 *   - `created_at`: set automatically on insert
 *   - `updated_at`: updated automatically on every update
 *
 * Column names are snake_case thanks to the SnakeNamingStrategy.
 */
export abstract class BaseEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @CreateDateColumn()
  createdAt: Date;

  @UpdateDateColumn()
  updatedAt: Date;
}
